//==============================================================================
// FB_INST_ADM100W
// Trumeter ADM100W power meter, Modbus RTU, 32-bit float MSW first (ABCD). No command : local mode is only reported
// 1. INPUTS     : requests, control mode, command source, equipment feedback -> INTERN
// 2. PROCESSING : on INTERN only
// 3. OUTPUTS    : INTERN -> COM / IO / EXC
// Control mode  : local HMI (individual or global) > auto (functional units)
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	//--- Control mode requests (HMI, global HMI local from UPI_LOCAL_HMI)
	INTERN.HMI_LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.HMI_AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_HMI  := EXC.UPI_INPUT_GLOBAL_LOCAL_HMI;

	//--- Control mode
	// Individual memory : set by the local request, reset by the auto request (auto wins if both)
	IF INTERN.HMI_LOCAL_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.HMI_AUTO_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := FALSE;
	END_IF

	// Resulting mode : HMI local (individual OR global), otherwise auto
	INTERN.LOCAL_HMI := INTERN.LOCAL_HMI_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_HMI;
	INTERN.AUTO      := NOT INTERN.LOCAL_HMI;

	//--- COM : alarms (coils 0..9)
	INTERN.ALARM_1  := COM.COM_INPUT_COILS[0].0;
	INTERN.ALARM_2  := COM.COM_INPUT_COILS[0].1;
	INTERN.ALARM_3  := COM.COM_INPUT_COILS[0].2;
	INTERN.ALARM_4  := COM.COM_INPUT_COILS[0].3;
	INTERN.ALARM_5  := COM.COM_INPUT_COILS[0].4;
	INTERN.ALARM_6  := COM.COM_INPUT_COILS[0].5;
	INTERN.ALARM_7  := COM.COM_INPUT_COILS[0].6;
	INTERN.ALARM_8  := COM.COM_INPUT_COILS[0].7;
	INTERN.ALARM_9  := COM.COM_INPUT_COILS[1].0;
	INTERN.ALARM_10 := COM.COM_INPUT_COILS[1].1;

	//--- COM : measures (input registers, MSW first)
	INTERN.FREQUENCY                 := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[0], Low_word := COM.COM_INPUT_IR[1]);
	INTERN.L1_L2_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[2], Low_word := COM.COM_INPUT_IR[3]);
	INTERN.L1_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[4], Low_word := COM.COM_INPUT_IR[5]);
	INTERN.L1_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[6], Low_word := COM.COM_INPUT_IR[7]);
	INTERN.L1_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[8], Low_word := COM.COM_INPUT_IR[9]);
	INTERN.L1_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[10], Low_word := COM.COM_INPUT_IR[11]);
	INTERN.L1_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[12], Low_word := COM.COM_INPUT_IR[13]);
	INTERN.L1_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[14], Low_word := COM.COM_INPUT_IR[15]);
	INTERN.L1_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[16], Low_word := COM.COM_INPUT_IR[17]);
	INTERN.L1_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[18], Low_word := COM.COM_INPUT_IR[19]);
	INTERN.L1_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[20], Low_word := COM.COM_INPUT_IR[21]);
	INTERN.L1_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[22], Low_word := COM.COM_INPUT_IR[23]);
	INTERN.L1_L2_VOLTAGE_PHASE_ANGLE := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[24], Low_word := COM.COM_INPUT_IR[25]);
	INTERN.L2_L3_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[26], Low_word := COM.COM_INPUT_IR[27]);
	INTERN.L2_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[28], Low_word := COM.COM_INPUT_IR[29]);
	INTERN.L2_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[30], Low_word := COM.COM_INPUT_IR[31]);
	INTERN.L2_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[32], Low_word := COM.COM_INPUT_IR[33]);
	INTERN.L2_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[34], Low_word := COM.COM_INPUT_IR[35]);
	INTERN.L2_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[36], Low_word := COM.COM_INPUT_IR[37]);
	INTERN.L2_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[38], Low_word := COM.COM_INPUT_IR[39]);
	INTERN.L2_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[40], Low_word := COM.COM_INPUT_IR[41]);
	INTERN.L2_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[42], Low_word := COM.COM_INPUT_IR[43]);
	INTERN.L2_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[44], Low_word := COM.COM_INPUT_IR[45]);
	INTERN.L2_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[46], Low_word := COM.COM_INPUT_IR[47]);
	INTERN.L1_L3_VOLTAGE_PHASE_ANGLE := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[48], Low_word := COM.COM_INPUT_IR[49]);
	INTERN.L3_L1_VOLTAGE             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[50], Low_word := COM.COM_INPUT_IR[51]);
	INTERN.L3_N_VOLTAGE              := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[52], Low_word := COM.COM_INPUT_IR[53]);
	INTERN.L3_CURRENT                := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[54], Low_word := COM.COM_INPUT_IR[55]);
	INTERN.L3_ACTIVE_POWER           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[56], Low_word := COM.COM_INPUT_IR[57]);
	INTERN.L3_APPARENT_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[58], Low_word := COM.COM_INPUT_IR[59]);
	INTERN.L3_REACTIVE_POWER         := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[60], Low_word := COM.COM_INPUT_IR[61]);
	INTERN.L3_CURRENT_PHASE_ANGLE    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[62], Low_word := COM.COM_INPUT_IR[63]);
	INTERN.L3_POWER_FACTOR           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[64], Low_word := COM.COM_INPUT_IR[65]);
	INTERN.L3_VOLTAGE_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[66], Low_word := COM.COM_INPUT_IR[67]);
	INTERN.L3_CURRENT_THD            := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[68], Low_word := COM.COM_INPUT_IR[69]);
	INTERN.L3_MAX_LOAD               := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[70], Low_word := COM.COM_INPUT_IR[71]);
	INTERN.INTERNAL_TEMPERATURE      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[72], Low_word := COM.COM_INPUT_IR[73]);
	INTERN.ACTIVE_ENERGY             := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[74], Low_word := COM.COM_INPUT_IR[75]);
	INTERN.APPARENT_ENERGY           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[76], Low_word := COM.COM_INPUT_IR[77]);
	INTERN.REACTIVE_ENERGY           := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[78], Low_word := COM.COM_INPUT_IR[79]);
	INTERN.TOTAL_ACTIVE_POWER        := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[80], Low_word := COM.COM_INPUT_IR[81]);
	INTERN.TOTAL_APPARENT_POWER      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[82], Low_word := COM.COM_INPUT_IR[83]);
	INTERN.TOTAL_REACTIVE_POWER      := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[84], Low_word := COM.COM_INPUT_IR[85]);
	INTERN.ALL_PHASE_POWER_FACTOR    := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_IR[86], Low_word := COM.COM_INPUT_IR[87]);


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	// Nothing


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- COM : control mode status to HMI
	COM.HMI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_HMI;

	//--- EXC
	EXC.EXC_OUTPUT_FREQUENCY            := INTERN.FREQUENCY;
	EXC.EXC_OUTPUT_L1_N_VOLTAGE         := INTERN.L1_N_VOLTAGE;
	EXC.EXC_OUTPUT_L1_CURRENT           := INTERN.L1_CURRENT;
	EXC.EXC_OUTPUT_L1_ACTIVE_POWER      := INTERN.L1_ACTIVE_POWER;
	EXC.EXC_OUTPUT_L1_APPARENT_POWER    := INTERN.L1_APPARENT_POWER;
	EXC.EXC_OUTPUT_L1_REACTIVE_POWER    := INTERN.L1_REACTIVE_POWER;
	EXC.EXC_OUTPUT_L1_POWER_FACTOR      := INTERN.L1_POWER_FACTOR;
	EXC.EXC_OUTPUT_L1_VOLTAGE_THD       := INTERN.L1_VOLTAGE_THD;
	EXC.EXC_OUTPUT_L1_CURRENT_THD       := INTERN.L1_CURRENT_THD;
	EXC.EXC_OUTPUT_L1_MAX_LOAD          := INTERN.L1_MAX_LOAD;
	EXC.EXC_OUTPUT_INTERNAL_TEMPERATURE := INTERN.INTERNAL_TEMPERATURE;
	EXC.EXC_OUTPUT_ACTIVE_ENERGY        := INTERN.ACTIVE_ENERGY;
	// EXC.EXC_OUTPUT_DATA_VALID : not managed yet (no Modbus diagnostic)

	//--- COM : alarms to HMI
	COM.HMI_OUTPUT_ALARM_1_STATUS  := INTERN.ALARM_1;
	COM.HMI_OUTPUT_ALARM_2_STATUS  := INTERN.ALARM_2;
	COM.HMI_OUTPUT_ALARM_3_STATUS  := INTERN.ALARM_3;
	COM.HMI_OUTPUT_ALARM_4_STATUS  := INTERN.ALARM_4;
	COM.HMI_OUTPUT_ALARM_5_STATUS  := INTERN.ALARM_5;
	COM.HMI_OUTPUT_ALARM_6_STATUS  := INTERN.ALARM_6;
	COM.HMI_OUTPUT_ALARM_7_STATUS  := INTERN.ALARM_7;
	COM.HMI_OUTPUT_ALARM_8_STATUS  := INTERN.ALARM_8;
	COM.HMI_OUTPUT_ALARM_9_STATUS  := INTERN.ALARM_9;
	COM.HMI_OUTPUT_ALARM_10_STATUS := INTERN.ALARM_10;

	//--- COM : measures to HMI
	COM.HMI_OUTPUT_FREQUENCY.Real_value                 := INTERN.FREQUENCY;
	COM.HMI_OUTPUT_L1_L2_VOLTAGE.Real_value             := INTERN.L1_L2_VOLTAGE;
	COM.HMI_OUTPUT_L1_N_VOLTAGE.Real_value              := INTERN.L1_N_VOLTAGE;
	COM.HMI_OUTPUT_L1_CURRENT.Real_value                := INTERN.L1_CURRENT;
	COM.HMI_OUTPUT_L1_ACTIVE_POWER.Real_value           := INTERN.L1_ACTIVE_POWER;
	COM.HMI_OUTPUT_L1_APPARENT_POWER.Real_value         := INTERN.L1_APPARENT_POWER;
	COM.HMI_OUTPUT_L1_REACTIVE_POWER.Real_value         := INTERN.L1_REACTIVE_POWER;
	COM.HMI_OUTPUT_L1_CURRENT_PHASE_ANGLE.Real_value    := INTERN.L1_CURRENT_PHASE_ANGLE;
	COM.HMI_OUTPUT_L1_POWER_FACTOR.Real_value           := INTERN.L1_POWER_FACTOR;
	COM.HMI_OUTPUT_L1_VOLTAGE_THD.Real_value            := INTERN.L1_VOLTAGE_THD;
	COM.HMI_OUTPUT_L1_CURRENT_THD.Real_value            := INTERN.L1_CURRENT_THD;
	COM.HMI_OUTPUT_L1_MAX_LOAD.Real_value               := INTERN.L1_MAX_LOAD;
	COM.HMI_OUTPUT_L1_L2_VOLTAGE_PHASE_ANGLE.Real_value := INTERN.L1_L2_VOLTAGE_PHASE_ANGLE;
	COM.HMI_OUTPUT_L2_L3_VOLTAGE.Real_value             := INTERN.L2_L3_VOLTAGE;
	COM.HMI_OUTPUT_L2_N_VOLTAGE.Real_value              := INTERN.L2_N_VOLTAGE;
	COM.HMI_OUTPUT_L2_CURRENT.Real_value                := INTERN.L2_CURRENT;
	COM.HMI_OUTPUT_L2_ACTIVE_POWER.Real_value           := INTERN.L2_ACTIVE_POWER;
	COM.HMI_OUTPUT_L2_APPARENT_POWER.Real_value         := INTERN.L2_APPARENT_POWER;
	COM.HMI_OUTPUT_L2_REACTIVE_POWER.Real_value         := INTERN.L2_REACTIVE_POWER;
	COM.HMI_OUTPUT_L2_CURRENT_PHASE_ANGLE.Real_value    := INTERN.L2_CURRENT_PHASE_ANGLE;
	COM.HMI_OUTPUT_L2_POWER_FACTOR.Real_value           := INTERN.L2_POWER_FACTOR;
	COM.HMI_OUTPUT_L2_VOLTAGE_THD.Real_value            := INTERN.L2_VOLTAGE_THD;
	COM.HMI_OUTPUT_L2_CURRENT_THD.Real_value            := INTERN.L2_CURRENT_THD;
	COM.HMI_OUTPUT_L2_MAX_LOAD.Real_value               := INTERN.L2_MAX_LOAD;
	COM.HMI_OUTPUT_L1_L3_VOLTAGE_PHASE_ANGLE.Real_value := INTERN.L1_L3_VOLTAGE_PHASE_ANGLE;
	COM.HMI_OUTPUT_L3_L1_VOLTAGE.Real_value             := INTERN.L3_L1_VOLTAGE;
	COM.HMI_OUTPUT_L3_N_VOLTAGE.Real_value              := INTERN.L3_N_VOLTAGE;
	COM.HMI_OUTPUT_L3_CURRENT.Real_value                := INTERN.L3_CURRENT;
	COM.HMI_OUTPUT_L3_ACTIVE_POWER.Real_value           := INTERN.L3_ACTIVE_POWER;
	COM.HMI_OUTPUT_L3_APPARENT_POWER.Real_value         := INTERN.L3_APPARENT_POWER;
	COM.HMI_OUTPUT_L3_REACTIVE_POWER.Real_value         := INTERN.L3_REACTIVE_POWER;
	COM.HMI_OUTPUT_L3_CURRENT_PHASE_ANGLE.Real_value    := INTERN.L3_CURRENT_PHASE_ANGLE;
	COM.HMI_OUTPUT_L3_POWER_FACTOR.Real_value           := INTERN.L3_POWER_FACTOR;
	COM.HMI_OUTPUT_L3_VOLTAGE_THD.Real_value            := INTERN.L3_VOLTAGE_THD;
	COM.HMI_OUTPUT_L3_CURRENT_THD.Real_value            := INTERN.L3_CURRENT_THD;
	COM.HMI_OUTPUT_L3_MAX_LOAD.Real_value               := INTERN.L3_MAX_LOAD;
	COM.HMI_OUTPUT_INTERNAL_TEMPERATURE.Real_value      := INTERN.INTERNAL_TEMPERATURE;
	COM.HMI_OUTPUT_ACTIVE_ENERGY.Real_value             := INTERN.ACTIVE_ENERGY;
	COM.HMI_OUTPUT_APPARENT_ENERGY.Real_value           := INTERN.APPARENT_ENERGY;
	COM.HMI_OUTPUT_REACTIVE_ENERGY.Real_value           := INTERN.REACTIVE_ENERGY;
	COM.HMI_OUTPUT_TOTAL_ACTIVE_POWER.Real_value        := INTERN.TOTAL_ACTIVE_POWER;
	COM.HMI_OUTPUT_TOTAL_APPARENT_POWER.Real_value      := INTERN.TOTAL_APPARENT_POWER;
	COM.HMI_OUTPUT_TOTAL_REACTIVE_POWER.Real_value      := INTERN.TOTAL_REACTIVE_POWER;
	COM.HMI_OUTPUT_ALL_PHASE_POWER_FACTOR.Real_value    := INTERN.ALL_PHASE_POWER_FACTOR;

//==============================================================================
// FB_INST_DIP1500
// Kamoer DIP1500 peristaltic pump, Modbus RTU, 32-bit low word first (CDAB)
// 1. INPUTS     : requests, control mode, command source, equipment feedback -> INTERN
// 2. PROCESSING : on INTERN only
// 3. OUTPUTS    : INTERN -> COM / IO / EXC
// Parameters    : pump configuration in PA (persistent), changed from the HMI in local HMI
// Control mode  : local HMI (individual or global) > auto (functional units)
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	//--- Control mode requests (HMI, global HMI local from UPI_LOCAL_HMI)
	INTERN.HMI_LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.HMI_AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_HMI  := EXC.UPI_INPUT_GLOBAL_LOCAL_HMI;

	//--- Control mode
	// Individual memory : set by the local request, reset by the auto request (auto wins if both)
	IF INTERN.HMI_LOCAL_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.HMI_AUTO_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := FALSE;
	END_IF

	// Resulting mode : HMI local (individual OR global), otherwise auto
	INTERN.LOCAL_HMI := INTERN.LOCAL_HMI_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_HMI;
	INTERN.AUTO      := NOT INTERN.LOCAL_HMI;

	//--- Command source : local HMI > auto (UPI)
	IF INTERN.LOCAL_HMI THEN
		INTERN.CMD_RUN            := COM.HMI_INPUT_MOTOR_START_STOP;
		INTERN.CMD_CLOCKWISE      := COM.HMI_INPUT_MOTOR_DIRECTION;
		INTERN.CMD_VOLUME_MODE    := COM.HMI_INPUT_OPERATION_MODE;
		INTERN.CMD_SPEED          := COM.HMI_INPUT_MOTOR_SPEED.Real_value;
		INTERN.CMD_RUN_SETPOINT   := COM.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Real_value;
		INTERN.PARAM_WRITE_ENABLE := COM.HMI_INPUT_PARAM_WRITE_ENABLE;
		INTERN.FLASH_SAVE_REQUEST := COM.HMI_INPUT_FLASH_SAVE;
	ELSE
		// Auto : functional units (UPI)
		INTERN.CMD_RUN            := EXC.UPI_INPUT_RUN;
		INTERN.CMD_CLOCKWISE      := EXC.UPI_INPUT_CLOCKWISE;
		INTERN.CMD_VOLUME_MODE    := EXC.UPI_INPUT_VOLUME_MODE;
		INTERN.CMD_SPEED          := EXC.UPI_INPUT_SPEED;
		INTERN.CMD_RUN_SETPOINT   := EXC.UPI_INPUT_RUN_SETPOINT;
		INTERN.PARAM_WRITE_ENABLE := FALSE;                        // configuration is never written in auto
		INTERN.FLASH_SAVE_REQUEST := FALSE;
	END_IF

	//--- Parameter source : values typed on the HMI in local HMI (nothing in auto)
	IF INTERN.LOCAL_HMI THEN
		INTERN.SRC_MAX_MOTOR_SPEED         := COM.HMI_INPUT_MAX_MOTOR_SPEED.Real_value;
		INTERN.SRC_CALIBRATION_COEFFICIENT := COM.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Real_value;
		INTERN.SRC_FOOT_SWITCH_INPUT_MODE  := COM.HMI_INPUT_FOOT_SWITCH_INPUT_MODE;
		INTERN.SRC_LIQUID_LEVEL_INPUT_MODE := COM.HMI_INPUT_LIQUID_LEVEL_INPUT_MODE;
		INTERN.SRC_STATE_OUTPUT_MODE       := COM.HMI_INPUT_STATE_OUTPUT_MODE;
		INTERN.SRC_COMMUNICATION_ADDRESS   := COM.HMI_INPUT_COMMUNICATION_ADDRESS;
		INTERN.SRC_BAUD_RATE_INDEX         := COM.HMI_INPUT_BAUD_RATE_INDEX;
	END_IF

	//--- COM : input registers 0x3001..0x3005
	INTERN.FBK_FIRMWARE_VERSION := COM.COM_INPUT_IR[0];
	INTERN.FBK_HARDWARE_VERSION := COM.COM_INPUT_IR[1];
	INTERN.FBK_TEMPERATURE      := COM.COM_INPUT_IR[2];
	INTERN.FBK_LEVEL_ALARM      := COM.COM_INPUT_IR[3];
	INTERN.FBK_DIGITAL_OUTPUT   := COM.COM_INPUT_IR[4];

	//--- COM : run counters 0x4007..0x400A (format depends on mode)
	IF INTERN.CMD_VOLUME_MODE THEN
		// Volume mode : 32-bit REAL (ml)
		INTERN.FBK_RUN_ACTUAL := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_HR_COUNTERS[1], Low_word := COM.COM_INPUT_HR_COUNTERS[0]);
		INTERN.FBK_RUN_TOTAL  := FNC_WORDS_TO_REAL(High_word := COM.COM_INPUT_HR_COUNTERS[3], Low_word := COM.COM_INPUT_HR_COUNTERS[2]);
	ELSE
		// Time mode : 32-bit UDINT (ms)
		INTERN.UDINT_TEMP     := SHL(WORD_TO_UDINT(COM.COM_INPUT_HR_COUNTERS[1]), 16) OR WORD_TO_UDINT(COM.COM_INPUT_HR_COUNTERS[0]);
		INTERN.FBK_RUN_ACTUAL := UDINT_TO_REAL(INTERN.UDINT_TEMP);
		INTERN.UDINT_TEMP     := SHL(WORD_TO_UDINT(COM.COM_INPUT_HR_COUNTERS[3]), 16) OR WORD_TO_UDINT(COM.COM_INPUT_HR_COUNTERS[2]);
		INTERN.FBK_RUN_TOTAL  := UDINT_TO_REAL(INTERN.UDINT_TEMP);
	END_IF


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	//--- Parameters (PA) : a value changed on the HMI (local HMI) is saved in PA
	// PA is persistent : it keeps its value after a restart or a download. Default = declaration value.
	// The cycle where the mode changes is ignored, so switching mode never overwrites PA.
	INTERN.SOURCE_CHANGED := INTERN.LOCAL_HMI <> INTERN.PREV_LOCAL_HMI;
	INTERN.PREV_LOCAL_HMI := INTERN.LOCAL_HMI;

	IF NOT INTERN.SOURCE_CHANGED THEN
		IF INTERN.SRC_MAX_MOTOR_SPEED <> INTERN.PREV_SRC_MAX_MOTOR_SPEED THEN
			PA.MAX_MOTOR_SPEED := INTERN.SRC_MAX_MOTOR_SPEED;
		END_IF
		IF INTERN.SRC_CALIBRATION_COEFFICIENT <> INTERN.PREV_SRC_CALIBRATION_COEFFICIENT THEN
			PA.CALIBRATION_COEFFICIENT := INTERN.SRC_CALIBRATION_COEFFICIENT;
		END_IF
		IF INTERN.SRC_FOOT_SWITCH_INPUT_MODE <> INTERN.PREV_SRC_FOOT_SWITCH_INPUT_MODE THEN
			PA.FOOT_SWITCH_INPUT_MODE := INTERN.SRC_FOOT_SWITCH_INPUT_MODE;
		END_IF
		IF INTERN.SRC_LIQUID_LEVEL_INPUT_MODE <> INTERN.PREV_SRC_LIQUID_LEVEL_INPUT_MODE THEN
			PA.LIQUID_LEVEL_INPUT_MODE := INTERN.SRC_LIQUID_LEVEL_INPUT_MODE;
		END_IF
		IF INTERN.SRC_STATE_OUTPUT_MODE <> INTERN.PREV_SRC_STATE_OUTPUT_MODE THEN
			PA.STATE_OUTPUT_MODE := INTERN.SRC_STATE_OUTPUT_MODE;
		END_IF
		IF INTERN.SRC_COMMUNICATION_ADDRESS <> INTERN.PREV_SRC_COMMUNICATION_ADDRESS THEN
			PA.COMMUNICATION_ADDRESS := INTERN.SRC_COMMUNICATION_ADDRESS;
		END_IF
		IF INTERN.SRC_BAUD_RATE_INDEX <> INTERN.PREV_SRC_BAUD_RATE_INDEX THEN
			PA.BAUD_RATE_INDEX := INTERN.SRC_BAUD_RATE_INDEX;
		END_IF
	END_IF

	INTERN.PREV_SRC_MAX_MOTOR_SPEED         := INTERN.SRC_MAX_MOTOR_SPEED;
	INTERN.PREV_SRC_CALIBRATION_COEFFICIENT := INTERN.SRC_CALIBRATION_COEFFICIENT;
	INTERN.PREV_SRC_FOOT_SWITCH_INPUT_MODE  := INTERN.SRC_FOOT_SWITCH_INPUT_MODE;
	INTERN.PREV_SRC_LIQUID_LEVEL_INPUT_MODE := INTERN.SRC_LIQUID_LEVEL_INPUT_MODE;
	INTERN.PREV_SRC_STATE_OUTPUT_MODE       := INTERN.SRC_STATE_OUTPUT_MODE;
	INTERN.PREV_SRC_COMMUNICATION_ADDRESS   := INTERN.SRC_COMMUNICATION_ADDRESS;
	INTERN.PREV_SRC_BAUD_RATE_INDEX         := INTERN.SRC_BAUD_RATE_INDEX;

	//--- Parameters used by the pump : always from PA
	INTERN.CMD_MAX_SPEED      := PA.MAX_MOTOR_SPEED;
	INTERN.CMD_CALIB_COEF     := PA.CALIBRATION_COEFFICIENT;
	INTERN.CMD_FOOT_MODE      := PA.FOOT_SWITCH_INPUT_MODE;
	INTERN.CMD_LEVEL_MODE     := PA.LIQUID_LEVEL_INPUT_MODE;
	INTERN.CMD_STATE_OUT_MODE := PA.STATE_OUTPUT_MODE;
	INTERN.CMD_ADDRESS        := PA.COMMUNICATION_ADDRESS;
	INTERN.CMD_BAUD_INDEX     := PA.BAUD_RATE_INDEX;

	//--- Parameter validity
	INTERN.PARAM_VALID := (WORD_TO_UINT(INTERN.CMD_ADDRESS) >= 1) AND (WORD_TO_UINT(INTERN.CMD_ADDRESS) <= 31)
	                      AND (WORD_TO_UINT(INTERN.CMD_BAUD_INDEX) <= 7)
	                      AND (INTERN.CMD_MAX_SPEED > 0.0) AND (INTERN.CMD_CALIB_COEF > 0.0);

	//--- Flash save : 1 s pulse on rising edge, only with valid parameters
	R_TRIG_FLASH(CLK := INTERN.FLASH_SAVE_REQUEST);
	TP_FLASH(IN := R_TRIG_FLASH.Q AND INTERN.PARAM_VALID, PT := T#1S);
	INTERN.CMD_SAVE_FLASH := TP_FLASH.Q;

	//--- Write triggers (rising edge channels)
	// Square wave 500 ms : each rising edge = one write request
	TON_PULSE(IN := NOT TON_PULSE.Q, PT := T#250MS);
	IF TON_PULSE.Q THEN
		INTERN.PULSE_500MS := NOT INTERN.PULSE_500MS;
	END_IF

	// Command trigger : automatic, 3 s of edges after any command change
	INTERN.CMD_CHANGED := (INTERN.CMD_RUN <> INTERN.PREV_RUN) OR (INTERN.CMD_CLOCKWISE <> INTERN.PREV_CLOCKWISE)
	                      OR (INTERN.CMD_VOLUME_MODE <> INTERN.PREV_VOLUME_MODE) OR (INTERN.CMD_SAVE_FLASH <> INTERN.PREV_SAVE_FLASH)
	                      OR (INTERN.CMD_SPEED <> INTERN.PREV_SPEED) OR (INTERN.CMD_MAX_SPEED <> INTERN.PREV_MAX_SPEED)
	                      OR (INTERN.CMD_RUN_SETPOINT <> INTERN.PREV_RUN_SETPOINT);
	INTERN.PREV_RUN          := INTERN.CMD_RUN;
	INTERN.PREV_CLOCKWISE    := INTERN.CMD_CLOCKWISE;
	INTERN.PREV_VOLUME_MODE  := INTERN.CMD_VOLUME_MODE;
	INTERN.PREV_SAVE_FLASH   := INTERN.CMD_SAVE_FLASH;
	INTERN.PREV_SPEED        := INTERN.CMD_SPEED;
	INTERN.PREV_MAX_SPEED    := INTERN.CMD_MAX_SPEED;
	INTERN.PREV_RUN_SETPOINT := INTERN.CMD_RUN_SETPOINT;

	TOF_CMD_WINDOW(IN := INTERN.CMD_CHANGED, PT := T#3S);
	INTERN.CMD_WINDOW  := TOF_CMD_WINDOW.Q;
	INTERN.CMD_TRIGGER := INTERN.CMD_WINDOW AND (INTERN.CMD_MAX_SPEED > 0.0) AND INTERN.PULSE_500MS;

	// Configuration trigger : only while writing is enabled and parameters are valid
	INTERN.CONFIG_TRIGGER := INTERN.PARAM_WRITE_ENABLE AND INTERN.PARAM_VALID AND INTERN.PULSE_500MS;


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- COM : control mode status to HMI
	COM.HMI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_HMI;

	//--- COM : Modbus RTU coils
	COM.COM_OUTPUT_COILS[0] := INTERN.CMD_RUN;           // 0x0001
	COM.COM_OUTPUT_COILS[1] := INTERN.CMD_CLOCKWISE;     // 0x0002
	COM.COM_OUTPUT_COILS[2] := INTERN.CMD_SAVE_FLASH;    // 0x0003
	COM.COM_OUTPUT_COILS[3] := INTERN.CMD_VOLUME_MODE;   // 0x0004

	//--- COM : Modbus RTU holding registers and write triggers
	// Command registers 0x4001..0x4006 (sent on the command trigger)
	FNC_REAL_TO_WORDS(Real_value := INTERN.CMD_SPEED,     High_word => COM.COM_OUTPUT_HR_CMD[1], Low_word => COM.COM_OUTPUT_HR_CMD[0]);   // 0x4001-4002
	FNC_REAL_TO_WORDS(Real_value := INTERN.CMD_MAX_SPEED, High_word => COM.COM_OUTPUT_HR_CMD[3], Low_word => COM.COM_OUTPUT_HR_CMD[2]);   // 0x4003-4004
	IF INTERN.CMD_VOLUME_MODE THEN
		// Run setpoint 0x4005-4006, volume mode : 32-bit REAL (ml)
		FNC_REAL_TO_WORDS(Real_value := INTERN.CMD_RUN_SETPOINT, High_word => COM.COM_OUTPUT_HR_CMD[5], Low_word => COM.COM_OUTPUT_HR_CMD[4]);
	ELSE
		// Run setpoint 0x4005-4006, time mode : 32-bit UDINT (ms)
		INTERN.UDINT_TEMP        := REAL_TO_UDINT(MAX(INTERN.CMD_RUN_SETPOINT, 0.0));
		COM.COM_OUTPUT_HR_CMD[4] := UDINT_TO_WORD(INTERN.UDINT_TEMP);
		COM.COM_OUTPUT_HR_CMD[5] := UDINT_TO_WORD(SHR(INTERN.UDINT_TEMP, 16));
	END_IF

	// Configuration registers 0x400B..0x4011 (sent on the configuration trigger), updated only while enabled and valid
	IF INTERN.PARAM_WRITE_ENABLE AND INTERN.PARAM_VALID THEN
		FNC_REAL_TO_WORDS(Real_value := INTERN.CMD_CALIB_COEF, High_word => COM.COM_OUTPUT_HR_CONFIG[1], Low_word => COM.COM_OUTPUT_HR_CONFIG[0]);   // 0x400B-400C
		COM.COM_OUTPUT_HR_CONFIG[2] := INTERN.CMD_FOOT_MODE;        // 0x400D
		COM.COM_OUTPUT_HR_CONFIG[3] := INTERN.CMD_LEVEL_MODE;       // 0x400E
		COM.COM_OUTPUT_HR_CONFIG[4] := INTERN.CMD_STATE_OUT_MODE;   // 0x400F
		COM.COM_OUTPUT_HR_CONFIG[5] := INTERN.CMD_ADDRESS;          // 0x4010
		COM.COM_OUTPUT_HR_CONFIG[6] := INTERN.CMD_BAUD_INDEX;       // 0x4011
	END_IF

	// Write triggers
	COM.COM_OUTPUT_CMD_TRIGGER    := INTERN.CMD_TRIGGER;
	COM.COM_OUTPUT_CONFIG_TRIGGER := INTERN.CONFIG_TRIGGER;

	//--- COM : feedback to HMI
	COM.HMI_OUTPUT_FIRMWARE_VERSION                          := INTERN.FBK_FIRMWARE_VERSION;
	COM.HMI_OUTPUT_HARDWARE_VERSION                          := INTERN.FBK_HARDWARE_VERSION;
	COM.HMI_OUTPUT_TEMPERATURE                               := INTERN.FBK_TEMPERATURE;
	COM.HMI_OUTPUT_FLOAT_LEVEL_ALARM                         := INTERN.FBK_LEVEL_ALARM;
	COM.HMI_OUTPUT_DIGITAL_OUTPUT_VALUE                      := INTERN.FBK_DIGITAL_OUTPUT;
	COM.HMI_OUTPUT_REAL_TIME_RUN_TIME_OR_VOLUME.Real_value   := INTERN.FBK_RUN_ACTUAL;
	COM.HMI_OUTPUT_ACCUMULATED_RUN_TIME_OR_VOLUME.Real_value := INTERN.FBK_RUN_TOTAL;

//==============================================================================
// FB_INST_DOSENSOR
// Dissolved oxygen sensor, analog signal + fault input + 2 calibration outputs
// 1. INPUTS     : requests, control mode, command source, equipment feedback -> INTERN
// 2. PROCESSING : on INTERN only
// 3. OUTPUTS    : INTERN -> COM / IO / EXC
// Control mode  : local HMI (individual or global) > auto (functional units)
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	//--- Control mode requests (HMI, global HMI local from UPI_LOCAL_HMI)
	INTERN.HMI_LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.HMI_AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;
	INTERN.GLOBAL_LOCAL_HMI  := EXC.UPI_INPUT_GLOBAL_LOCAL_HMI;

	//--- Control mode
	// Individual memory : set by the local request, reset by the auto request (auto wins if both)
	IF INTERN.HMI_LOCAL_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := TRUE;
	END_IF
	IF INTERN.HMI_AUTO_REQUEST THEN
		INTERN.LOCAL_HMI_INDIVIDUAL := FALSE;
	END_IF

	// Resulting mode : HMI local (individual OR global), otherwise auto
	INTERN.LOCAL_HMI := INTERN.LOCAL_HMI_INDIVIDUAL OR INTERN.GLOBAL_LOCAL_HMI;
	INTERN.AUTO      := NOT INTERN.LOCAL_HMI;

	//--- Command source : calibration requests (local HMI > auto)
	IF INTERN.LOCAL_HMI THEN
		INTERN.CALIB_HIGH_REQUEST := COM.HMI_INPUT_CALIBRATION_HIGH;
		INTERN.CALIB_LOW_REQUEST  := COM.HMI_INPUT_CALIBRATION_LOW;
	ELSE
		// Auto : functional units (UPI)
		INTERN.CALIB_HIGH_REQUEST := FALSE;
		INTERN.CALIB_LOW_REQUEST  := FALSE;
	END_IF

	//--- IO
	INTERN.SIGNAL_RAW := IO.INPUT_SIGNAL;
	INTERN.FAULT      := IO.INPUT_SENSOR_FAULT;


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	//--- Signal scaling
	INTERN.SIGNAL := (DWORD_TO_REAL(INTERN.SIGNAL_RAW * 40) / 65535) - 8;

	//--- Calibration : 1 s pulse to the sensor, 5 s "done" message
	TP_CALIB_HIGH(IN := INTERN.CALIB_HIGH_REQUEST, PT := T#1S);
	TP_CALIB_LOW(IN := INTERN.CALIB_LOW_REQUEST, PT := T#1S);
	TP_CALIB_DONE(IN := TP_CALIB_HIGH.Q OR TP_CALIB_LOW.Q, PT := T#5S);

	INTERN.CALIB_HIGH := TP_CALIB_HIGH.Q;
	INTERN.CALIB_LOW  := TP_CALIB_LOW.Q;
	INTERN.CALIB_DONE := TP_CALIB_DONE.Q;


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- COM : control mode status to HMI
	COM.HMI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_HMI;

	//--- EXC
	EXC.EXC_OUTPUT_SIGNAL := INTERN.SIGNAL;

	//--- IO
	IO.OUTPUT_CALIBRATION_HIGH := INTERN.CALIB_HIGH;
	IO.OUTPUT_CALIBRATION_LOW  := INTERN.CALIB_LOW;

	//--- COM : feedback to HMI
	COM.HMI_OUTPUT_SIGNAL.Real_value := INTERN.SIGNAL;
	COM.HMI_OUTPUT_FAULT             := INTERN.FAULT;
	COM.HMI_OUTPUT_CALIBRATION_DONE  := INTERN.CALIB_DONE;

//==============================================================================
// FB_UPI_LOCAL_HMI
// Global HMI local mode for every equipment
// Set by the HMI local request, reset by the HMI auto request (pulse or maintained, auto wins)
// The equipment read this status through GFC_EXC and report their own local status themselves
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	INTERN.LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	IF INTERN.LOCAL_REQUEST THEN
		INTERN.LOCAL_ACTIVE := TRUE;
	END_IF
	IF INTERN.AUTO_REQUEST THEN
		INTERN.LOCAL_ACTIVE := FALSE;
	END_IF


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- EXC : to every equipment (through GFC_EXC)
	EXC.UPI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;

	//--- COM : status
	COM.HMI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;

//==============================================================================
// FC_EXC_UPI_LOCAL_HMI_ADM100W
// Exchanges between one UPI_LOCAL_HMI instance and one ADM100W instance
// Called in GFC_EXC, once per pair of instances, with their GVL_EXC variables
// Simple copies only, no conversion
//==============================================================================

//--- UPI_LOCAL_HMI -> ADM100W
EXC_ADM100W.UPI_INPUT_GLOBAL_LOCAL_HMI := EXC_UPI_LOCAL_HMI.UPI_OUTPUT_LOCAL_ACTIVE;

FC_EXC_UPI_LOCAL_HMI_ADM100W := TRUE;

//==============================================================================
// FC_EXC_UPI_LOCAL_HMI_DIP1500
// Exchanges between one UPI_LOCAL_HMI instance and one DIP1500 instance
// Called in GFC_EXC, once per pair of instances, with their GVL_EXC variables
// Simple copies only, no conversion
//==============================================================================

//--- UPI_LOCAL_HMI -> DIP1500
EXC_DIP1500.UPI_INPUT_GLOBAL_LOCAL_HMI := EXC_UPI_LOCAL_HMI.UPI_OUTPUT_LOCAL_ACTIVE;

FC_EXC_UPI_LOCAL_HMI_DIP1500 := TRUE;

//==============================================================================
// FC_EXC_UPI_LOCAL_HMI_DOSENSOR
// Exchanges between one UPI_LOCAL_HMI instance and one DOSENSOR instance
// Called in GFC_EXC, once per pair of instances, with their GVL_EXC variables
// Simple copies only, no conversion
//==============================================================================

//--- UPI_LOCAL_HMI -> DOSENSOR
EXC_DOSENSOR.UPI_INPUT_GLOBAL_LOCAL_HMI := EXC_UPI_LOCAL_HMI.UPI_OUTPUT_LOCAL_ACTIVE;

FC_EXC_UPI_LOCAL_HMI_DOSENSOR := TRUE;

//==============================================================================
// FNC_REAL_TO_WORDS
// REAL (IEEE 754) -> two Modbus words
// Call: FNC_REAL_TO_WORDS(Real_value := x, High_word => ..., Low_word => ...);
//==============================================================================

Conversion.Real_value := Real_value;
Low_word  := Conversion.Word_value[0];
High_word := Conversion.Word_value[1];
FNC_REAL_TO_WORDS := TRUE;

//==============================================================================
// FNC_WORDS_TO_REAL
// Two Modbus words -> REAL (IEEE 754)
// ABCD device: High_word = lower address, CDAB device: Low_word = lower address
//==============================================================================

Conversion.Word_value[0] := Low_word;
Conversion.Word_value[1] := High_word;
FNC_WORDS_TO_REAL := Conversion.Real_value;

//==============================================================================
// GFB_INST
// Calls every equipment instance
// One block per equipment, all interfaces connected
//==============================================================================

//--- ADM100W_1 : Trumeter ADM100W power meter
FB_ADM100W_1(
	PA  := GVL_PA.PA_ADM100W_1,
	COM := GVL_COM.COM_ADM100W_1,
	EXC := GVL_EXC.EXC_ADM100W_1,
	IO  := GVL_IO.IO_ADM100W_1);

//--- DOSENSOR_1 : Dissolved oxygen sensor
FB_DOSENSOR_1(
	PA  := GVL_PA.PA_DOSENSOR_1,
	COM := GVL_COM.COM_DOSENSOR_1,
	EXC := GVL_EXC.EXC_DOSENSOR_1,
	IO  := GVL_IO.IO_DOSENSOR_1);

//--- DIP1500_1 : Kamoer DIP1500 peristaltic pump
FB_DIP1500_1(
	PA  := GVL_PA.PA_DIP1500_1,
	COM := GVL_COM.COM_DIP1500_1,
	EXC := GVL_EXC.EXC_DIP1500_1,
	IO  := GVL_IO.IO_DIP1500_1);

//==============================================================================
// GFB_UPI
// Calls every functional unit (UPI)
// Runs before GFB_INST, results go to the equipment through GFC_EXC
//==============================================================================

//--- UPI_LOCAL_HMI : Global HMI local mode
FB_UPI_LOCAL_HMI_1(
	COM := GVL_COM.COM_UPI_LOCAL_HMI,
	EXC := GVL_EXC.EXC_UPI_LOCAL_HMI);

//==============================================================================
// GFC_COM_IN
// Modbus (GVL_MODBUS) -> GVL_COM : RTU equipment, HMI
// Simple copies only, no conversion (conversions are done in the FBs)
//==============================================================================

//------------------------------------------------------------------------------
// COM : Modbus RTU, from equipment
//------------------------------------------------------------------------------
	//--- ADM100W_1
	GVL_COM.COM_ADM100W_1.COM_INPUT_IR    := GVL_MODBUS.ADM100W_InputRegisters;   // Input registers 0..87
	GVL_COM.COM_ADM100W_1.COM_INPUT_COILS := GVL_MODBUS.ADM100W_Alarms;           // Coils 0..9 (alarms)

	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.COM_INPUT_IR          := GVL_MODBUS.DIP1500_InputRegisters;     // Input registers 0x3001..0x3005
	GVL_COM.COM_DIP1500_1.COM_INPUT_HR_COUNTERS := GVL_MODBUS.DIP1500_Holding_Counters;   // Holding registers 0x4007..0x400A


//------------------------------------------------------------------------------
// HMI : coils (1...)
//------------------------------------------------------------------------------
	//--- DOSENSOR_1
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_CALIBRATION_HIGH := GVL_MODBUS.Coils_TCP_HMI[0].0;   // 1 | DO Calibration High
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_CALIBRATION_LOW  := GVL_MODBUS.Coils_TCP_HMI[0].1;   // 2 | DO Calibration Low
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_LOCAL_REQUEST    := GVL_MODBUS.Coils_TCP_HMI[0].7;   // 8 | DO Sensor Local Request
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_AUTO_REQUEST     := GVL_MODBUS.Coils_TCP_HMI[1].0;   // 9 | DO Sensor Auto Request

	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_START_STOP   := GVL_MODBUS.Coils_TCP_HMI[0].2;   // 3 | DIP1500 Motor Start Stop
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_DIRECTION    := GVL_MODBUS.Coils_TCP_HMI[0].3;   // 4 | DIP1500 Motor Direction
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLASH_SAVE         := GVL_MODBUS.Coils_TCP_HMI[0].4;   // 5 | DIP1500 Flash Save
	GVL_COM.COM_DIP1500_1.HMI_INPUT_OPERATION_MODE     := GVL_MODBUS.Coils_TCP_HMI[0].5;   // 6 | DIP1500 Operation Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_PARAM_WRITE_ENABLE := GVL_MODBUS.Coils_TCP_HMI[0].6;   // 7 | DIP1500 Parameter Write Enable
	GVL_COM.COM_DIP1500_1.HMI_INPUT_LOCAL_REQUEST      := GVL_MODBUS.Coils_TCP_HMI[1].1;   // 10 | DIP1500 Local Request
	GVL_COM.COM_DIP1500_1.HMI_INPUT_AUTO_REQUEST       := GVL_MODBUS.Coils_TCP_HMI[1].2;   // 11 | DIP1500 Auto Request

	//--- ADM100W_1
	GVL_COM.COM_ADM100W_1.HMI_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[1].3;   // 12 | ADM100W Local Request
	GVL_COM.COM_ADM100W_1.HMI_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[1].4;   // 13 | ADM100W Auto Request

	//--- UPI_LOCAL_HMI
	GVL_COM.COM_UPI_LOCAL_HMI.HMI_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[1].5;   // 14 | Global Local HMI Request
	GVL_COM.COM_UPI_LOCAL_HMI.HMI_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[1].6;   // 15 | Global Auto HMI Request


//------------------------------------------------------------------------------
// HMI : holding registers (1...), REAL = low word first
//------------------------------------------------------------------------------
	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_SPEED.Word_value[0]                                := GVL_MODBUS.Holding_register_TCP_HMI[0];   // 1 | DIP1500 Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_SPEED.Word_value[1]                                := GVL_MODBUS.Holding_register_TCP_HMI[1];   // 2 | DIP1500 Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MAX_MOTOR_SPEED.Word_value[0]                            := GVL_MODBUS.Holding_register_TCP_HMI[2];   // 3 | DIP1500 Max Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MAX_MOTOR_SPEED.Word_value[1]                            := GVL_MODBUS.Holding_register_TCP_HMI[3];   // 4 | DIP1500 Max Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[0]                := GVL_MODBUS.Holding_register_TCP_HMI[4];   // 5 | DIP1500 Run Time Or Volume Setpoint (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[1]                := GVL_MODBUS.Holding_register_TCP_HMI[5];   // 6 | DIP1500 Run Time Or Volume Setpoint (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[0] := GVL_MODBUS.Holding_register_TCP_HMI[6];   // 7 | DIP1500 Flow Rate Or Speed Calibration Coefficient (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[1] := GVL_MODBUS.Holding_register_TCP_HMI[7];   // 8 | DIP1500 Flow Rate Or Speed Calibration Coefficient (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FOOT_SWITCH_INPUT_MODE                                   := GVL_MODBUS.Holding_register_TCP_HMI[8];   // 9 | DIP1500 Foot Switch Input Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_LIQUID_LEVEL_INPUT_MODE                                  := GVL_MODBUS.Holding_register_TCP_HMI[9];   // 10 | DIP1500 Liquid Level Input Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_STATE_OUTPUT_MODE                                        := GVL_MODBUS.Holding_register_TCP_HMI[10];   // 11 | DIP1500 State Output Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_COMMUNICATION_ADDRESS                                    := GVL_MODBUS.Holding_register_TCP_HMI[11];   // 12 | DIP1500 Communication Address
	GVL_COM.COM_DIP1500_1.HMI_INPUT_BAUD_RATE_INDEX                                          := GVL_MODBUS.Holding_register_TCP_HMI[12];   // 13 | DIP1500 Baud Rate Index

GFC_COM_IN := TRUE;

//============================================================================== // GFC_COM_OUT // GVL_COM -> Modbus (GVL_MODBUS) : RTU equipment, HMI // Simple copies only, no conversion (conversions are done in the FBs) //==============================================================================
//------------------------------------------------------------------------------ // COM : Modbus RTU, to equipment (write triggers are mapped directly in the slave I/O mapping) //------------------------------------------------------------------------------ //--- DIP1500_1 GVL_MODBUS.DIP1500_Coils := GVL_COM.COM_DIP1500_1.COM_OUTPUT_COILS; // Coils 0x0001..0x0004 GVL_MODBUS.DIP1500_Holding_Cmd := GVL_COM.COM_DIP1500_1.COM_OUTPUT_HR_CMD; // Holding registers 0x4001..0x4006 GVL_MODBUS.DIP1500_Holding_Config := GVL_COM.COM_DIP1500_1.COM_OUTPUT_HR_CONFIG; // Holding registers 0x400B..0x4011
//------------------------------------------------------------------------------ // HMI : discrete inputs (10001...) //------------------------------------------------------------------------------ //--- DOSENSOR_1 GVL_MODBUS.Discret_input_TCP_HMI[0].0 := GVL_COM.COM_DOSENSOR_1.HMI_OUTPUT_FAULT; // 10001 | Do sensor fault GVL_MODBUS.Discret_input_TCP_HMI[0].1 := GVL_COM.COM_DOSENSOR_1.HMI_OUTPUT_CALIBRATION_DONE; // 10002 | Do sensor calibration done GVL_MODBUS.Discret_input_TCP_HMI[1].5 := GVL_COM.COM_DOSENSOR_1.HMI_OUTPUT_LOCAL_ACTIVE; // 10014 | DO Sensor Local Active
//--- ADM100W_1 GVL_MODBUS.Discret_input_TCP_HMI[0].2 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_1_STATUS; // 10003 | ADM100W Alarm 1 Status GVL_MODBUS.Discret_input_TCP_HMI[0].3 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_2_STATUS; // 10004 | ADM100W Alarm 2 Status GVL_MODBUS.Discret_input_TCP_HMI[0].4 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_3_STATUS; // 10005 | ADM100W Alarm 3 Status GVL_MODBUS.Discret_input_TCP_HMI[0].5 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_4_STATUS; // 10006 | ADM100W Alarm 4 Status GVL_MODBUS.Discret_input_TCP_HMI[0].6 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_5_STATUS; // 10007 | ADM100W Alarm 5 Status GVL_MODBUS.Discret_input_TCP_HMI[0].7 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_6_STATUS; // 10008 | ADM100W Alarm 6 Status GVL_MODBUS.Discret_input_TCP_HMI[1].0 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_7_STATUS; // 10009 | ADM100W Alarm 7 Status GVL_MODBUS.Discret_input_TCP_HMI[1].1 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_8_STATUS; // 10010 | ADM100W Alarm 8 Status GVL_MODBUS.Discret_input_TCP_HMI[1].2 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_9_STATUS; // 10011 | ADM100W Alarm 9 Status GVL_MODBUS.Discret_input_TCP_HMI[1].3 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_ALARM_10_STATUS; // 10012 | ADM100W Alarm 10 Status GVL_MODBUS.Discret_input_TCP_HMI[2].1 := GVL_COM.COM_ADM100W_1.HMI_OUTPUT_LOCAL_ACTIVE; // 10018 | ADM100W Local Active
